input.command:
cat > src/claim-office.spec.ts <<'EOF'
import { describe, it } from "vitest";

// Observable contract readings adopted where the specification leaves them open:
// - The specification defines rejection only at the CLI level ("exits with a
//   non-zero status code and writes an error description to stderr"). The most
//   defensible reading is that the domain layer signals rejection by throwing an
//   Error, and the CLI adapter translates a thrown Error into exit code 1 plus a
//   stderr message. Tests below state which layer they observe.
// - "A building block of 3 alike components" is read, per the spec examples, as
//   exactly-3 groups of the identical component type (4 runes => no block).

describe("MHPCO Claim Office", () => {
  // --- Quote: processing fee and the item catalogue ---
  it.todo("quotes an empty item list as premium 5 G (processing fee only)");
  it.todo("quotes a single plain sword as premium 105 G (100 G base + 5 G fee)");
  it.todo("quotes a single plain amulet as premium 65 G (60 G base + 5 G fee)");
  it.todo("quotes a single plain staff as premium 85 G (80 G base + 5 G fee)");
  it.todo("quotes a single plain potion as premium 45 G (40 G base + 5 G fee)");
  it.todo("quotes a single rune as premium 30 G (25 G base + 5 G fee)");
  it.todo("quotes a single moonstone as premium 30 G (25 G base + 5 G fee)");
  it.todo("quotes a sword and an amulet as premium 165 G (100 + 60 base + 5 G fee)");

  // --- Quote: component building blocks ---
  it.todo("quotes 2 runes as base premium 50 G (no block) -- premium 55 G");
  it.todo("quotes 3 runes as base premium 60 G (block applies) -- premium 65 G");
  it.todo("quotes 4 runes as base premium 100 G (no block; block requires exactly 3) -- premium 105 G");
  it.todo("quotes 7 runes as base premium 175 G (no block at 7) -- premium 180 G");
  it.todo("quotes 2 runes + 1 moonstone as base premium 75 G (no block: different types) -- premium 80 G");
  it.todo("quotes 3 runes + 3 moonstones as base premium 120 G (two separate blocks) -- premium 125 G");
  it.todo("quotes 3 moonstones as base premium 60 G (block applies to moonstones too) -- premium 65 G");

  // --- Quote: item-specific modifiers ---
  it.todo("adds a 50 % curse surcharge on the cursed item's base premium: cursed sword => 100 + 50 + 5 = 155 G for a loyal repeat customer scenario-free case");
  it.todo("adds a 30 % high-enchantment surcharge at enchantment exactly 5: sword => 100 + 30 + 5 = 135 G");
  it.todo("adds no high-enchantment surcharge at enchantment 4: sword => 100 + 5 = 105 G");
  it.todo("applies both curse and high-enchantment surcharges to a cursed sword with enchantment 5 => 100 + 50 + 30 + 5 = 185 G");
  it.todo("applies the curse surcharge only to the cursed item, not the policy total: cursed sword + plain amulet => 160 base + 50 curse + 5 fee = 215 G");

  // --- Quote: policy-wide modifiers ---
  it.todo("applies a 20 % loyalty discount at exactly 2 years with MHPCO: sword => 100 - 20 + 5 = 85 G");
  it.todo("applies no loyalty discount at 1 year with MHPCO: sword => 100 + 5 = 105 G");
  it.todo("applies the 10 % first-insurance surcharge to a newcomer's first quote: sword, 0 years => 100 + 10 + 5 = 115 G");
  it.todo("applies the 15 % follow-up-contract discount to a customer's second quote: sword, 0 years, second quote => 100 + 10 - 15 + 5 = 100 G");
  it.todo("applies the first-insurance surcharge on every quote, regardless of customer history (each quoted item is a first insurance)");
  it.todo("applies the loyalty discount to the policy base premium (sum of item base premiums), not per item: two swords, 2 years => 200 - 40 + 5 = 165 G");

  // --- Quote: rounding in MHPCO's favour ---
  it.todo("rounds a premium of 197.5 G up to 198 G (MHPCO's favour)");
  it.todo("keeps intermediate amounts fractional and rounds only the final premium");

  // --- Quote: integration examples ---
  it.todo("integration: newcomer (0 years, no previous contract) with a cursed steel sword (ench. 3) => premium 165 G");
  it.todo("integration: 3-year customer's second quote with a cursed steel sword (ench. 7) => premium 160 G");

  // --- Quote: rejection ---
  it.todo("rejects a quote containing an unknown item type (e.g. broomstick) by throwing an Error (CLI: non-zero exit, error on stderr, no results on stdout)");

  // --- Claim: standard reimbursement and deductible ---
  it.todo("pays out 400 G for a regular steel sword (ench. 3) with damage 500 G (full reimbursement minus 100 G deductible)");
  it.todo("pays out 100 G for a damaged rune (value 250 G) with damage 200 G (no enchantment or material => no special clause)");
  it.todo("applies the 100 G deductible once per damaged item: sword 500 G + amulet 300 G in one incident => payout 600 G");

  // --- Claim: special clauses ---
  it.todo("reimburses 50 % for enchantment exactly 8: dragon sword ench. 8, damage 1000 G => payout 400 G");
  it.todo("fully reimburses dragon material at enchantment 5: dragon sword, damage 800 G => payout 700 G");
  it.todo("prefers the 50 % clause when both apply: dragon sword ench. 9, damage 1000 G => payout 400 G");
  it.todo("applies the 50 % clause alone for a steel sword ench. 9, damage 1000 G => payout 400 G");
  it.todo("never pays a negative amount: damage 50 G below the 100 G deductible => payout 0 G");

  // --- Claim: insurance sum and cap ---
  it.todo("caps a policy at twice the insurance sum: sword + amulet => insurance sum 1600 G, cap 3200 G");
  it.todo("bases the cap on unmodified insurance values: cursed sword (premium 165 G) => cap 2000 G");
  it.todo("counts each of two swords in the insurance sum: two swords => insurance sum 2000 G, cap 4000 G");
  it.todo("ignores the block discount in the insurance sum: sword + 3 runes => insurance sum 1750 G, cap 3500 G");
  it.todo("reports remainingCap after a claim: sword policy (cap 2000 G), claim 1500 G => payout 1400 G, remainingCap 600 G");
  it.todo("limits a second claim to the remaining cap: second claim 1500 G => payout 600 G, remainingCap 0 G");

  // --- Claim: multiple items of the same type ---
  it.todo("treats two sword damage entries on a two-sword policy as separate damages with their own deductibles");
  it.todo("rejects a claim with more damage entries of a type than the policy covers (two sword damages, one sword insured) by throwing an Error (CLI: non-zero exit)");

  // --- Claim: rounding in MHPCO's favour ---
  it.todo("rounds a payout of 350.5 G down to 350 G (MHPCO's favour)");

  // --- Claim: rejection ---
  it.todo("rejects a claim whose damaged item is not part of the policy (amulet damaged, only a sword insured) by throwing an Error (CLI: non-zero exit)");
  it.todo("rejects a claim referencing an unknown item type by throwing an Error (CLI: non-zero exit)");
  it.todo("rejects a claim with a negative damage amount (-200) by throwing an Error (CLI: non-zero exit)");

  // --- CLI adapter ---
  it.todo("CLI: reads the schema example scenario from stdin and writes {results:[{premium},{payout,remainingCap}]} to stdout");
  it.todo("CLI: processes steps sequentially so a claim step resolves its policy by zero-based quote step index");
  it.todo("CLI: exits with a non-zero status code and writes an error description to stderr for an invalid scenario, writing no results to stdout");
});
EOF
echo written

