export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
}

const PROCESSING_FEE = 5;

const COMPONENT_BASE_PREMIUM = 25;
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_BASE_PREMIUM = 60;

const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

const COMPONENT_TYPES = ["rune", "moonstone"];

function isComponent(type: string): boolean {
  return COMPONENT_TYPES.includes(type);
}

function itemBasePremium(type: string): number {
  return isComponent(type) ? COMPONENT_BASE_PREMIUM : MAIN_ITEM_BASE_PREMIUMS[type];
}

function countByType(items: Item[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
}

// The MHPCO offers the building block on components. No active example prices a
// group of three alike main items, so the size test below is not yet qualified
// by `isComponent`; qualify it when such an example is activated.
function alikeGroupBasePremium(type: string, count: number): number {
  if (count === COMPONENT_BLOCK_SIZE) {
    return COMPONENT_BLOCK_BASE_PREMIUM;
  }
  return count * itemBasePremium(type);
}

function policyBasePremium(items: Item[]): number {
  let total = 0;
  for (const [type, count] of countByType(items)) {
    total += alikeGroupBasePremium(type, count);
  }
  return total;
}

export function quote(customer: Customer, items: Item[]): number {
  return policyBasePremium(items) + PROCESSING_FEE;
}

