  );
}

// Policy-wide modifiers apply to the policy base premium, not to any single item.
function policyWideModifiers(
  customer: Customer,
  precedingContracts: number,
  basePremium: number,
): number {
  return policyWideRate(customer, precedingContracts) * basePremium;
}'''
assert old in s
