old2='''export function quote(customer: Customer, items: Item[]): number {
  const basePremium = policyBasePremium(items);
  const premiumBeforeFee =
    basePremium + itemSurcharges(items) + policyWideModifiers(customer, basePremium);
  return premiumBeforeFee + PROCESSING_FEE;
}'''
new2='''export function quote(customer: Customer, items: Item[], precedingContracts = 0): number {
  const basePremium = policyBasePremium(items);
  const premiumBeforeFee =
    basePremium +
    itemSurcharges(items) +
    policyWideModifiers(customer, precedingContracts, basePremium);
  return premiumBeforeFee + PROCESSING_FEE;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export type Step = QuoteStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export type StepResult = QuoteResult;

// A scenario is one customer's sequence of operations. Every contract after the
// customer's first in the scenario earns the follow-up-contract discount.
export function runScenario(scenario: Scenario): { results: StepResult[] } {
  const results: StepResult[] = [];
  let contracts = 0;
  for (const step of scenario.steps) {
    results.push({ premium: quote(scenario.customer, step.items, contracts) });
    contracts += 1;
  }
  return { results };
}'''
