s=s.replace('''const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {''','''const COMPONENT_INSURANCE_VALUE = 250;

const MAIN_ITEM_INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
};

const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {''')
s=s.replace('''export type Step = QuoteStep;''','''export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export type Step = QuoteStep | ClaimStep;''')
s=s.replace('''export type StepResult = QuoteResult;''','''export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

// The MHPCO insures each item at its price-list insurance value; the block
// discount affects the premium only, not the insurance sum.
function itemInsuranceValue(type: string): number {
  return isComponent(type) ? COMPONENT_INSURANCE_VALUE : MAIN_ITEM_INSURANCE_VALUES[type];
}

function insuranceSum(items: Item[]): number {
  return items.reduce((total, item) => total + itemInsuranceValue(item.type), 0);
}

// A policy the MHPCO has written: the items it covers and the payout cap still
// available on it.
interface Policy {
  items: Item[];
  remainingCap: number;
}

// The MHPCO reimburses a damage in full, less the deductible that applies to
// every damage event.
function damagePayout(damage: Damage): number {
  return damage.amount - DEDUCTIBLE_PER_DAMAGE;
}

// The MHPCO rounds in its own favour: a payout is rounded down.
function roundedPayout(payout: number): number {
  return Math.floor(payout);
}

function settleClaim(policy: Policy, incident: Incident): ClaimResult {
  const payout = roundedPayout(
    incident.damages.reduce((total, damage) => total + damagePayout(damage), 0),
  );
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
}''')
