    });
    precedingContracts += 1;
  }
  return { results };'''
new='''  const results: StepResult[] = [];
  const policies = new Map<number, Policy>();
  let precedingContracts = 0;
  scenario.steps.forEach((step, index) => {
    if (step.op === "quote") {
      results.push({
        premium: roundedPremium(quote(scenario.customer, step.items, precedingContracts)),
      });
      policies.set(index, {
        items: step.items,
        remainingCap: CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSum(step.items),
      });
      precedingContracts += 1;
      return;
    }
    const policy = policies.get(step.policy);
    if (policy === undefined) {
      throw new Error(`Claim refers to step ${String(step.policy)}, which wrote no policy`);
    }
    results.push(settleClaim(policy, step.incident));
  });
  return { results };'''
