input.command:
python3 - <<'PY'
p='src/claim-office.spec.ts'
s=open(p).read()
old='  it.todo("CLI: exits with a non-zero status code and writes an error description to stderr for an invalid scenario, writing no results to stdout");'
new='''  it("CLI: exits with a non-zero status code and writes an error description to stderr for an invalid scenario, writing no results to stdout", () => {
    const stdin = JSON.stringify({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "broomstick" }] }],
    });
    let status = 0;
    let stdout = "";
    let stderr = "";
    try {
      execFileSync("npx", ["tsx", "src/cli.ts"], { input: stdin, encoding: "utf8" });
    } catch (failure) {
      const spawn = failure as { status: number; stdout: string; stderr: string };
      status = spawn.status;
      stdout = spawn.stdout;
      stderr = spawn.stderr;
    }
    expect(status).not.toBe(0);
    expect(stdout).toBe("");
    expect(stderr).toMatch(/broomstick/);
  });'''
assert old in s
s=s.replace(old,new); open(p,'w').write(s)
PY
npx vitest run 2>&1 | grep -E "expected|Tests " | head -4

